html:
{%- macro emp(e) -%}{{ (frappe.db.get_value("Employee", e, "employee_name") or e) if e else "" }}{%- endmacro -%}
{%- macro dt(v) -%}{{ frappe.format(v, {"fieldtype": "Date"}) if v else "" }}{%- endmacro -%}
{%- macro txt(v) -%}{{ (v | e | replace("\n", "<br>")) if v else "" }}{%- endmacro -%}
{%- macro header() -%}
	<table class="hdr">
		<tr>
			<td style="width:28%">355 Gus Hipp Blvd.<br>Rockledge, FL 32955</td>
			<td style="width:44%; text-align:center"><img src="{{ frappe.utils.get_url('/assets/hse/images/psif_logo.jpg') }}" style="height:52px"></td>
			<td style="width:28%; text-align:right">Tel: (321) 636-0085<br><b>www.psifla.com</b></td>
		</tr>
	</table>
	<h1>{{ _("QM-128 Corrective Action & Preventative Action (CAPA) Report") }}</h1>
{%- endmacro -%}
{%- macro footer(page) -%}
	<table class="foot">
		<tr>
			<td style="width:25%">{{ _("Page {0} of 2").format(page) }}</td>
			<td style="width:50%; text-align:center">{{ _("QM-128 Corrective Action & Preventative Action (CAPA) Report") }}</td>
			<td style="width:25%; text-align:right">{{ _("Rev. 2: 09/26") }}</td>
		</tr>
	</table>
{%- endmacro -%}
{%- set related = doc.capa_related_ncrs or [] -%}
{%- set initiator = doc.capa_initiated_by_name or (frappe.db.get_value("User", doc.capa_initiated_by, "full_name") if doc.capa_initiated_by else "") or doc.capa_initiated_by or "" -%}
<style>
	.capa { font-family: Arial, Helvetica, sans-serif; color: #000; font-size: 11px; }
	.print-format .capa td, .capa td { padding: 3px 6px !important; vertical-align: top; line-height: 1.3; }
	.capa table { width: 100%; border-collapse: collapse; table-layout: fixed; }
	.capa .hdr td { vertical-align: middle; font-size: 9px; }
	.capa h1 { font-size: 19px; font-weight: bold; text-align: center; margin: 6px 0 4px 0; padding-bottom: 3px; border-bottom: 1px solid #555; }
	.capa .page2 { page-break-before: always; }
	.capa .proc { margin: 14px 10px 0 10px; font-size: 11px; line-height: 1.35; }
	.capa .proc ol.top { padding-left: 18px; margin: 0; }
	.capa .proc ol.top > li { margin-bottom: 12px; font-weight: bold; }
	.capa .proc ol.top > li > span.b { font-size: 14px; }
	.capa .proc .n { font-weight: normal; }
	.capa .proc h4 { font-size: 11px; font-weight: bold; margin: 6px 0 2px 20px; }
	.capa .proc ul { margin: 2px 0 6px 0; padding-left: 52px; font-weight: normal; list-style-type: disc; }
	.capa .proc ul ul { padding-left: 26px; list-style-type: circle; margin: 0; }
	.capa .proc h3 { font-size: 13px; margin: 18px 0 4px 0; }
	.capa .grid { margin-top: 8px; }
	.capa .grid td { border: 1px solid #000; height: 20px; vertical-align: middle; }
	.capa .grid .lbl { text-align: right; width: 18%; }
	.capa .box { margin-top: 8px; }
	.capa .box td { border: 1px solid #000; }
	.capa .box td.f { height: 20px; vertical-align: middle; }
	.capa .box td.t { height: 34px; }
	.capa .box td.tall { height: 44px; }
	.capa .box .v { margin-top: 2px; }
	.capa .box .v p { margin: 0 0 2px 0; }
	.capa .rule { font-size: 10px; line-height: 1.4; }
	.capa .rule .due { float: right; font-weight: bold; }
	.capa .whys td { border: none; border-bottom: 1px dotted #000; height: 16px; padding: 2px 4px !important; vertical-align: top; }
	.capa .whys tr:last-child td { border-bottom: none; }
	.capa .whys .w { width: 13%; font-weight: bold; }
	.capa .foot { margin-top: 8px; font-size: 9px; page-break-inside: avoid; }
</style>
<div class="capa">
	{{ header() }}
	<div class="proc">
		<ol class="top">
			<li><span class="b">{{ _("Definition:") }}</span> <span class="n">{{ _("CAPA refers to a process designed to identify, investigate, and address the root causes of non-conformances (corrective actions) and potential issues that could lead to non-conformances (preventive actions).") }}</span></li>
			<li><span class="b">{{ _("Purpose:") }}</span> <span class="n">{{ _("The goal of CAPA is to eliminate the causes of existing non-conformances, to prevent recurrence (corrective action) and to identify and eliminate potential causes of non-conformances to prevent their occurrence (preventive action).") }}</span></li>
			<li><span class="b">{{ _("Process:") }}</span>
				<h4>3.1 {{ _("CAPA Identification Parameters:") }}</h4>
				<ul>
					<li>{{ _("The Quality Department employees will be responsible for identifying, creating and logging all CAPAs in the Nonconformance & Improvement Tracking Workspace (Smartsheet).") }}</li>
					<li>{{ _("CAPAs will be created based on trended NCR issues reoccurring with similar failures and/or failure modes (> 5 occurrences)") }}</li>
				</ul>
				<h4>3.2 {{ _("CAPA Basic Process:") }}</h4>
				<ul>
					<li>{{ _("Corrective Action:") }}
						<ul>
							<li>{{ _("Identification of the non-conformance.") }}</li>
							<li>{{ _("Investigation and analysis to determine the root cause.") }}</li>
							<li>{{ _("Implementation of actions to eliminate the root cause.") }}</li>
							<li>{{ _("Verification to ensure the effectiveness of the corrective action.") }}</li>
						</ul>
					</li>
					<li>{{ _("Preventive Action:") }}
						<ul>
							<li>{{ _("Identification of potential non-conformances.") }}</li>
							<li>{{ _("Risk assessment to determine the likelihood and impact.") }}</li>
							<li>{{ _("Implementation of actions to prevent the occurrence of potential issues.") }}</li>
							<li>{{ _("Monitoring to ensure the effectiveness of the preventive action.") }}</li>
						</ul>
					</li>
				</ul>
			</li>
			<li><span class="b">{{ _("Outcome:") }}</span> <span class="n">{{ _("The outcome of CAPA is the elimination or reduction of the root causes of existing or potential non-conformances, leading to continuous improvement in the quality management system.") }}</span></li>
		</ol>
		<h3>{{ _("Summary") }}</h3>
		<div><b>CAPA</b>: {{ _("Focuses on investigating the root causes of non-conformances and implementing actions to prevent recurrence (corrective) or prevent occurrence (preventive).") }}</div>
	</div>
	<div style="height:150px"></div>
	{{ footer(1) }}

	<div class="page2">
	{{ header() }}
	<table class="grid">
		<tr><td class="lbl">{{ _("CAPA #:") }}</td><td>{{ doc.capa_no or "" }}</td><td class="lbl" style="width:20%">{{ _("Initiated By:") }}</td><td>{{ initiator }}</td></tr>
		<tr><td class="lbl">{{ _("CAPA Status:") }}</td><td>{{ _(doc.capa_status) if doc.capa_status else "" }}</td><td class="lbl">{{ _("Initiated Date:") }}</td><td>{{ dt(doc.capa_initiated_date) }}</td></tr>
		<tr><td class="lbl">{{ _("CAPA Source:") }}</td><td>{{ _(doc.capa_source) if doc.capa_source else "" }}</td><td class="lbl">{{ _("NCR #:") }}</td><td>{{ doc.ncr_no or "" }}{% if not doc.ncr_no %}<span style="font-size:8px; color:#555">{{ _("ERPNext") }} {{ doc.name }}</span>{% endif %}{% if related %}<br><span style="font-size:9px">{{ _("Related:") }} {% for r in related %}{{ frappe.db.get_value("Nonconformance Report", r.non_conformance, "ncr_no") or r.non_conformance }}{{ ", " if not loop.last else "" }}{% endfor %}</span>{% endif %}</td></tr>
	</table>

	<table class="box">
		<tr><td class="f" colspan="2">{{ _("Part Number/Description:") }} {{ doc.capa_part_description or "" }}</td></tr>
		<tr><td class="f">{{ _("Assigned To:") }} {{ emp(doc.capa_assigned_to) }}</td><td class="f">{{ _("Assigned Date:") }} {{ dt(doc.capa_assigned_date) }}</td></tr>
		<tr><td class="f">{{ _("Extension Approval:") }} {{ emp(doc.capa_extension_approved_by) }}</td><td class="f">{{ _("Due Date Extended Until:") }} {{ dt(doc.capa_extended_until) }}</td></tr>
		<tr><td class="f" colspan="2">{{ _("Justification for Extension:") }} {{ txt(doc.capa_extension_justification) }}</td></tr>
		<tr><td colspan="2" class="rule">
			{{ _("Containment due within 7 days of initiation") }}{% if doc.capa_containment_due %}<span class="due">{{ dt(doc.capa_containment_due) }}</span>{% endif %}<br>
			{{ _("Correction due 30 days after initiation unless an extension is approved by the Management Representative") }}{% if doc.capa_correction_due %}<span class="due">{{ dt(doc.capa_correction_due) }}</span>{% endif %}<br>
			{{ _("Closure due within 60 days of initiation unless an extension is approved by the Management Representative") }}{% if doc.capa_closure_due %}<span class="due">{{ dt(doc.capa_closure_due) }}</span>{% endif %}
		</td></tr>
	</table>

	<table class="box">
		<tr><td class="tall" colspan="2">{{ _("Finding:") }}<div class="v">{{ doc.capa_finding or "" }}</div></td></tr>
		<tr><td class="t" colspan="2">{{ _("Containment/Correction:") }}<div class="v">{{ doc.capa_containment or "" }}</div></td></tr>
		<tr><td colspan="2" style="padding:0 !important">
			<table class="whys">
				<colgroup><col style="width:13%"><col style="width:87%"></colgroup>
				<tr><td colspan="2" style="border-bottom:1px solid #000"><b>{{ _("5 Whys Root Cause Analysis") }}</b></td></tr>
				<tr><td class="w">{{ _("Problem:") }}</td><td>{{ txt(doc.why_problem) }}</td></tr>
				{%- for n in range(1, 6) %}
				<tr><td class="w">{{ _("Why {0}?").format(n) }}</td><td>{{ txt(doc.get("why_" ~ n)) }}</td></tr>
				{%- endfor %}
			</table>
		</td></tr>
		<tr><td class="t" colspan="2">{{ _("Root Cause:") }}<div class="v">{{ doc.capa_root_cause or "" }}</div></td></tr>
		<tr><td class="f" colspan="2">{{ _("Contributing Human Factor if applicable:") }} {{ txt(doc.capa_human_factor) }}</td></tr>
		<tr><td class="t" colspan="2">{{ _("Corrective Action:") }}<div class="v">{{ doc.capa_corrective_action or "" }}</div></td></tr>
		<tr><td class="t" colspan="2">{{ _("Preventive Action:") }}<div class="v">{{ doc.capa_preventive_action or "" }}</div></td></tr>
		<tr><td class="f" style="width:50%">{{ _("Quality Verification:") }} {{ _(doc.capa_quality_verification) if doc.capa_quality_verification else "" }}{% if doc.capa_verified_by %} - {{ emp(doc.capa_verified_by) }}{% endif %}</td><td class="f">{{ _("Verification Date:") }} {{ dt(doc.capa_verification_date) }}</td></tr>
		<tr><td class="t" colspan="2">{{ _("Follow-Up:") }}<div class="v">{{ txt(doc.capa_follow_up) }}</div></td></tr>
		<tr><td class="f">{{ _("Closed By:") }} {{ emp(doc.capa_closed_by) }}</td><td class="f">{{ _("Closure Date:") }} {{ dt(doc.capa_closure_date) }}</td></tr>
	</table>
	{{ footer(2) }}
	</div>
</div>
